def sop(id, title, category, severity, summary, objective, scope, triggers, tools, roles, steps, queries, escalation, mitre, closure):
    return {"id": id, "title": title, "category": category, "severity": severity, "summary": summary, "objective": objective, "scope": scope,
            "triggers": triggers, "tools": tools, "roles": roles, "steps": steps, "queries": queries, "escalation": escalation, "sla": SLA,
            "mitre": mitre, "closure": closure, "version": "1.2", "updated": "2026-06-01"}


